#include <bits/stdc++.h>
using namespace std;
#define LL long long
#define MAXN 250005

int Mod;

int bin_pow(int base, int exp) {
    LL result=1, cur=base;
    while (exp>0) {
        if (exp&1) result=result*cur%Mod;
        cur=cur*cur%Mod;
        exp>>=1;
    }
    return (int)result;
}

int n, k;
int factorials[MAXN], inv_factorials[MAXN], inverses[MAXN], memo[19][MAXN];

int dfs(int used, int subset) {
    if (memo[used][subset]!=-1) return memo[used][subset];
    int answer=0;
    if (subset==0) {
        answer=factorials[n];
        for (int i=1;i<=used;++i)
            answer=1LL*answer*(k-i+1)%Mod;
        return memo[used][subset]=answer;
    }
    if (used>k) return 0;
    int lowest_bit = subset & (-subset);
    int remaining = subset - lowest_bit;
    for (int T=remaining;; T=(T-1)&remaining) {
        answer=(answer+1LL*inv_factorials[subset - T]*dfs(used+1,T)%Mod)%Mod;
        if (T==0) break;
    }
    return memo[used][subset]=answer;
}

int main() {
    scanf("%d%d%d",&n,&k,&Mod);
    if (n%2==1) {
        printf("%d\n",bin_pow(k,n));
        return 0;
    }
    factorials[0]=inv_factorials[0]=1;
    factorials[1]=inv_factorials[1]=1;
    for (int i=2;i<=n;++i) {
        factorials[i]=1LL*factorials[i-1]*i%Mod;
        inverses[i]=1LL*(Mod - Mod/i)*inv_factorials[Mod%i]%Mod;
        inv_factorials[i]=1LL*inv_factorials[i-1]*inverses[i]%Mod;
    }
    for (int i=0;i<=18;++i)
        for (int j=0;j<=n;++j)
            memo[i][j]=-1;
    printf("%d\n",(bin_pow(k,n)-dfs(0,n)+Mod)%Mod);
    return 0;
}
